    Bug 1979580 - Allow the user to change the open file limit on Windows. r=mkmelin


    Unlike Linux/macOS, Windows requires the application to set the maximum number
    of open file descriptors (`_setmaxstdio`). This patch adds support for reading
    the `MOZ_MAXSTDIO` environment variable on startup, allowing users to raise the
    default 512 limit up to 8192. For debugging, lowering the limit is also possible
    down to the minimum accepted value of 3 (though not recommended).

    Differential Revision: https://phabricator.services.mozilla.com/D274934

diff --git a/mail/app/nsMailApp.cpp b/mail/app/nsMailApp.cpp
index fc4362153cd..f156e2b2e76 100644
--- a/mail/app/nsMailApp.cpp
+++ b/mail/app/nsMailApp.cpp
@@ -215,6 +215,24 @@ static int do_main(int argc, char* argv[], char* envp[]) {
   const char* acceptableParams[] = {"compose", "mail", nullptr};
   EnsureCommandlineSafe(argc, argv, acceptableParams);

+#ifdef XP_WIN
+  //  Allow the user to raise the number of files that may be open
+  //  simultaneously by setting an environment variable.
+  const char* mozMaxstdio = getenv("MOZ_MAXSTDIO");
+  if (mozMaxstdio) {
+    int limit = atoi(mozMaxstdio);
+    int newLimit = -1;
+    if (limit >= 3 && limit <= 8192) {
+      newLimit = _setmaxstdio(limit);
+    }
+    if (newLimit != limit) {
+      Output(
+          "The open file limit could not be set from the MOZ_MAXSTDIO "
+          "environment variable.\n");
+    }
+  }
+#endif
+
   return gBootstrap->XRE_main(argc, argv, config);
 }
